"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Beacon of the Valtor Nebula', 'author': 'Signature original', 'genre': 'Colony Worlds', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "Commander Sera Ilsa gave the order anyway. The engines lit, the deck hummed, and the ship leapt toward a star chart etched in crystal with the Valtor Nebula falling behind. Some cargoes, Commander Sera Ilsa knew, are worth the whole sky.\n\nIn the hold, under work lights, Commander Sera Ilsa studied a star chart etched in crystal. It pulsed faintly, like a heart. 'the frontier tests us all,' Commander Sera Ilsa murmured. 'Let's find out what you are.'\n\nThey grappled a star chart etched in crystal with the cargo arm as the first raider shells crossed their bow. Dr. Ilsa Venn whooped as the airlock sealed. Whatever a star chart etched in crystal was, it was theirs now — and Warlord Krell knew it."}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "'It's a map,' breathed Commander Sera Ilsa, 'and a warning.' The route it drew cut through the worst of the drift: plasma storms, minefields, and the patrol lanes of Warlord Krell.\n\nDr. Ilsa Venn cracked a star chart etched in crystal's casing with a spanner and a prayer. Inside: coordinates, a starlog, a voice saying one word over and over — the name of the Valtor Nebula.\n\nThe crew voted — that was Commander Sera Ilsa's rule, always a vote before a suicide run. Every hand went up. Dr. Ilsa Venn grinned. 'We didn't sign on for safe,' they said."}, {'n': 3, 'title': 'Storm Season', 'text': "The plasma storm hit at the second waypoint, a wall of fire across the sky. Dr. Ilsa Venn rerouted everything to the shields, hands flying, while Commander Sera Ilsa threaded the ship through gaps that opened and closed like eyes.\n\nAfterward, Commander Sera Ilsa looked at each face on the bridge and said it plainly: 'There's a traitor aboard. I don't know who. But a star chart etched in crystal goes to the Valtor Nebula — with all of us, or with whoever's left.'\n\nThe battle was short and ugly. Commander Sera Ilsa used the storm itself as a weapon, luring the flagship into a plasma surge that stripped its shields. They escaped in the glare, hull scorched, crew cheering raggedly."}, {'n': 4, 'title': "The Traitor's Price", 'text': "Then a star chart etched in crystal spoke — fully, at last. Not a map but a key, and not to a place but to a shield: an ancient defense grid sleeping around the Valtor Nebula, the only thing that could stop Warlord Krell's fleet.\n\nCommander Sera Ilsa laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' Dr. Ilsa Venn was already calculating the wake-up sequence.\n\nCommander Sera Ilsa let them live, confined to quarters. 'Warlord Krell trades in hostages,' Commander Sera Ilsa told the crew. 'We trade in something better.' It was a gamble; the crew's eyes said they knew it."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "The duel was legend before it ended: two ships in the fire-light, neither yielding, until Commander Sera Ilsa did the impossible — dove through the grid's own gate, which a star chart etched in crystal held open, and watched Warlord Krell break against the shield they could not see.\n\nDr. Ilsa Venn fed a star chart etched in crystal into the ancient console. For a heartbeat nothing happened — then the sky caught fire, a lattice of light wrapping the Valtor Nebula like a held breath. Warlord Krell's vanguard shattered against it like waves on rock.\n\nThe flagship came on anyway, and Commander Sera Ilsa met it ship to ship above the burning sky. It was Warlord Krell themselves on the viewscreen, offering one last deal. Commander Sera Ilsa answered with the engines at full burn."}, {'n': 6, 'title': 'Home Signal', 'text': "Dr. Ilsa Venn was offered an admiralty and laughed in the committee's face. 'I have a ship,' they said. It was the highest compliment the crew had ever heard.\n\nThe traitor's family was found and freed; the traitor wept and was forgiven, and signed on again — this time for real. Commander Sera Ilsa's rule about second chances held, barely, and gloriously.\n\nThey landed at the Valtor Nebula to crowds and bells. The old voice from the starlog had belonged to the grid's last keeper, dead a hundred years; a star chart etched in crystal was their final message. Commander Sera Ilsa laid it in the memorial with honors."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

